import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel for RMS LayerNorm
cuda_source = """
#include <cuda.h>
#include <cuda_fp16.h>
#include <cuda_bf16.h>
#include <cmath>

// Warp-level reduction using shuffle
__device__ __forceinline__ float warp_reduce_sum(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}

__global__ void rms_layernorm_forward_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    float* __restrict__ Y,
    float* __restrict__ r,
    const int N,
    const int D,
    const float eps
) {
    const int row = blockIdx.x;
    const int tid = threadIdx.x;
    const int lane_id = tid & 31;
    const int warp_id = tid >> 5;
    const int num_warps = blockDim.x >> 5;

    if (row >= N) return;

    // Pointers to current row
    const float* x_row = X + row * D;
    float* y_row = Y + row * D;

    // Compute sum of squares
    float sum_sq = 0.0f;

    // Each thread processes multiple elements
    for (int col = tid; col < D; col += blockDim.x) {
        float val = x_row[col];
        sum_sq += val * val;
    }

    // Warp-level reduction
    sum_sq = warp_reduce_sum(sum_sq);

    // Shared memory for cross-warp reduction
    __shared__ float s_partial[32];  // Max 32 warps per block

    if (lane_id == 0) {
        s_partial[warp_id] = sum_sq;
    }
    __syncthreads();

    // First warp does final reduction
    if (warp_id == 0) {
        sum_sq = (lane_id < num_warps) ? s_partial[lane_id] : 0.0f;
        sum_sq = warp_reduce_sum(sum_sq);

        if (lane_id == 0) {
            float mean_sq = sum_sq / D;
            float inv_rms = rsqrtf(mean_sq + eps);
            r[row] = inv_rms;
            s_partial[0] = inv_rms;  // Broadcast to all threads
        }
    }
    __syncthreads();

    float inv_rms = s_partial[0];

    // Apply normalization and weights
    for (int col = tid; col < D; col += blockDim.x) {
        float normed = x_row[col] * inv_rms;
        y_row[col] = normed * W[col];
    }
}

// BF16 version
__global__ void rms_layernorm_forward_kernel_bf16(
    const __nv_bfloat16* __restrict__ X,
    const __nv_bfloat16* __restrict__ W,
    __nv_bfloat16* __restrict__ Y,
    float* __restrict__ r,
    const int N,
    const int D,
    const float eps
) {
    const int row = blockIdx.x;
    const int tid = threadIdx.x;
    const int lane_id = tid & 31;
    const int warp_id = tid >> 5;
    const int num_warps = blockDim.x >> 5;

    if (row >= N) return;

    // Pointers to current row
    const __nv_bfloat16* x_row = X + row * D;
    __nv_bfloat16* y_row = Y + row * D;

    // Compute sum of squares
    float sum_sq = 0.0f;

    // Each thread processes multiple elements
    for (int col = tid; col < D; col += blockDim.x) {
        float val = __bfloat162float(x_row[col]);
        sum_sq += val * val;
    }

    // Warp-level reduction
    sum_sq = warp_reduce_sum(sum_sq);

    // Shared memory for cross-warp reduction
    __shared__ float s_partial[32];

    if (lane_id == 0) {
        s_partial[warp_id] = sum_sq;
    }
    __syncthreads();

    // First warp does final reduction
    if (warp_id == 0) {
        sum_sq = (lane_id < num_warps) ? s_partial[lane_id] : 0.0f;
