        }
    }
    __syncthreads();

    float inv_rms = s_partial[0];

    // Apply normalization and weights
    for (int col = tid; col < D; col += blockDim.x) {
        float x_val = __bfloat162float(x_row[col]);
        float w_val = __bfloat162float(W[col]);
        float normed = x_val * inv_rms;
        y_row[col] = __float2bfloat16(normed * w_val);
    }
}

// Vectorized load/store version for better memory throughput
__global__ void rms_layernorm_forward_kernel_bf16_vec4(
    const __nv_bfloat16* __restrict__ X,
    const __nv_bfloat16* __restrict__ W,
    __nv_bfloat16* __restrict__ Y,
    float* __restrict__ r,
    const int N,
    const int D,
    const float eps
) {
    const int row = blockIdx.x;
    const int tid = threadIdx.x;
    const int lane_id = tid & 31;
    const int warp_id = tid >> 5;
    const int num_warps = blockDim.x >> 5;

    if (row >= N) return;

    // Use float4 for vectorized loads (8 bf16 values at a time)
    const float4* x_row_vec = reinterpret_cast<const float4*>(X + row * D);
    float4* y_row_vec = reinterpret_cast<float4*>(Y + row * D);
    const float4* w_vec = reinterpret_cast<const float4*>(W);
    const int vec_size = D / 8;  // Number of float4 elements

    // Compute sum of squares
    float sum_sq = 0.0f;

    // Vectorized load and process
    for (int i = tid; i < vec_size; i += blockDim.x) {
        float4 x_vec = x_row_vec[i];
        __nv_bfloat162* x_bf16 = reinterpret_cast<__nv_bfloat162*>(&x_vec);

        // Process 2 bf16 pairs at a time (4 pairs total = 8 bf16 values)
        #pragma unroll
        for (int j = 0; j < 4; j++) {
            float2 vals = __bfloat1622float2(x_bf16[j]);
            sum_sq += vals.x * vals.x + vals.y * vals.y;
        }
    }

    // Handle remaining elements
    const int remainder_start = vec_size * 8;
    const __nv_bfloat16* x_row = X + row * D;
    for (int col = remainder_start + tid; col < D; col += blockDim.x) {
        float val = __bfloat162float(x_row[col]);
        sum_sq += val * val;
    }

    // Warp-level reduction
    sum_sq = warp_reduce_sum(sum_sq);

    // Shared memory for cross-warp reduction
    __shared__ float s_partial[32];

    if (lane_id == 0) {
        s_partial[warp_id] = sum_sq;
    }
    __syncthreads();

    // First warp does final reduction
    if (warp_id == 0) {
        sum_sq = (lane_id < num_warps) ? s_partial[lane_id] : 0.0f;
        sum_sq = warp_reduce_sum(sum_sq);

        if (lane_id == 0) {
            float mean_sq = sum_sq / D;
            float inv_rms = rsqrtf(mean_sq + eps);
            r[row] = inv_rms;
            s_partial[0] = inv_rms;
        }
    }
    __syncthreads();

    float inv_rms = s_partial[0];

    // Vectorized store
    for (int i = tid; i < vec_size; i += blockDim.x) {
        float4 x_vec = x_row_vec[i];
        float4 w_vec_val = w_vec[i];
        float4 y_vec;

        __nv_bfloat162* x_bf16 = reinterpret_cast<__nv_bfloat162*>(&x_vec);
        __nv_bfloat162* w_bf16 = reinterpret_cast<__nv_bfloat162*>(&w_vec_val);
        __nv_bfloat162* y_bf16 = reinterpret_cast<__nv_bfloat162*>(&y_vec);

        #pragma unroll
        for (int j = 0; j < 4; j++) {
            float2 x_vals = __bfloat1622float2(x_bf16[j]);
            float2 w_vals = __bfloat1622float2(w_bf16[j]);
            float2 y_vals;
            y_vals.x = x_vals.x * inv_rms * w_vals.x;
            y_vals.y = x_vals.y * inv_rms * w_vals.y;
            y_bf16[j] = __float22bfloat162_rn(y_vals);
        }

        y_row_vec[i] = y_vec;
    }

    // Handle remaining elements
    __nv_bfloat16* y_row = Y + row * D;
    for (int col = remainder_start + tid; col < D; col += blockDim.x) {
        float x_val = __bfloat162float(x_row[col]);
        float w_val = __bfloat162float(W[col]);
        float normed = x_val * inv_rms;
        y_row[col] = __float2bfloat16(normed * w_val);
    }
}

torch::Tensor rms_layernorm_forward(torch::Tensor x, torch::Tensor w) {
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(w.dim() == 1, "w must be 1D");

    const int N = x.size(0);
    const int D = x.size(1);

    auto y = torch::empty_like(x);
    auto r = torch::empty({N}, torch::TensorOptions().dtype(torch::kFloat32).device(x.device()));

    const float eps = 1e-6f;

    // Choose block size based on D
    int block_size = (D + 127) / 128 * 128;
    block_size = min(block_size, 1024);
    block_size = max(block_size, 32);

    if (x.scalar_type() == torch::kFloat32) {
        rms_layernorm_forward_kernel<<<N, block_size>>>(
            x.data_ptr<float>(),
            w.data_ptr<float>(),
            y.data_ptr<float>(),
            r.data_ptr<float>(),
            N, D, eps
        );
    } else if (x.scalar_type() == torch::kBFloat16) {
        // Use vectorized kernel if D is divisible by 8
        if (D % 8 == 0) {
            rms_layernorm_forward_kernel_bf16_vec4<<<N, block_size>>>(
                reinterpret_cast<const __nv_bfloat16*>(x.data_ptr<at::BFloat16>()),
                reinterpret_cast<const __nv_bfloat16*>(w.data_ptr<at::BFloat16>()),
                reinterpret_cast<__nv_bfloat16*>(y.data_ptr<at::BFloat16>()),
                r.data_ptr<float>(),
                N, D, eps
            );
        } else {
            rms_layernorm_forward_kernel_bf16<<<N, block_size>>>(
                reinterpret_cast<const __nv_bfloat16*>(x.data_ptr<at::BFloat16>()),
                reinterpret_cast<const __nv_bfloat16*>(w.data_ptr<at::BFloat16>()),
                reinterpret_cast<__nv_bfloat16*>(y.data_ptr<at::BFloat16>()),
                r.data_ptr<float>(),
                N, D, eps
            );
        }
    } else {
        TORCH_CHECK(false, "Unsupported dtype");
    }

    return y;
}
"""

