__device__ __forceinline__ float block_reduce_sum(float val, float* s_partial, int num_warps) {
    const int lane_id = threadIdx.x & 31;
    const int warp_id = threadIdx.x >> 5;

    val = warp_reduce_sum(val);

    if (lane_id == 0) {
        s_partial[warp_id] = val;
    }
    __syncthreads();

    if (warp_id == 0) {
        val = (lane_id < num_warps) ? s_partial[lane_id] : 0.0f;
        val = warp_reduce_sum(val);
    }
    return val;
}

// FP32 kernel with vectorized loads (float4)
__global__ __launch_bounds__(256, 4) void rms_layernorm_forward_kernel_fp32(
    const float* __restrict__ X,
    const float* __restrict__ W,
    float* __restrict__ Y,
    float* __restrict__ r,
    const int N,
    const int D,
    const float eps
) {
    const int row = blockIdx.x;
    const int tid = threadIdx.x;
    const int lane_id = tid & 31;
    const int warp_id = tid >> 5;
    const int num_warps = blockDim.x >> 5;

    if (row >= N) return;

    // Pointers to current row
    const float* x_row = X + row * D;
    float* y_row = Y + row * D;

    // Shared memory for reduction
    __shared__ float s_partial[32];

    // Compute sum of squares with vectorized loads
    float sum_sq = 0.0f;

    // Use scalar loads to avoid alignment issues
    for (int i = tid; i < D; i += blockDim.x) {
        float v = __ldg(&x_row[i]);
        sum_sq += v * v;
