    sum_sq = block_reduce_sum(sum_sq, s_partial, num_warps);

    float inv_rms;
    if (threadIdx.x == 0) {
        float mean_sq = sum_sq / D;
        inv_rms = rsqrtf(mean_sq + eps);
        r[row] = inv_rms;
        s_partial[0] = inv_rms;
    }
    __syncthreads();

    inv_rms = s_partial[0];

    // Apply normalization and weights
    for (int i = tid; i < D; i += blockDim.x) {
        float xv = __ldg(&x_row[i]);
        float wv = __ldg(&W[i]);
        y_row[i] = xv * inv_rms * wv;
    }
