    const __nv_bfloat162* w_2 = reinterpret_cast<const __nv_bfloat162*>(W);
    __nv_bfloat162* y_row_2 = reinterpret_cast<__nv_bfloat162*>(y_row);

    for (int i = tid; i < n2; i += blockDim.x) {
